<?php

declare(strict_types=1);

namespace Ritmo\Tests\Support;

use Ritmo\Domain\Model\NightType;
use Ritmo\Domain\Model\PaceStatus;

/**
 * Access to the golden fixtures dumped from the reference Python engine
 * (tests/fixtures/golden, generated by tests/fixtures/tools/dump_golden.py).
 *
 * Case inputs use the engine's argument names and vocabulary; the helpers below translate the
 * vocabulary into the plugin's types.
 */
final class Golden
{
    /** Largest accepted difference for amounts; percentages and integers must match exactly. */
    public const AMOUNT_TOLERANCE = 0.01;

    /** What the dump writes in place of a NaN result. */
    public const NAN = 'NaN';

    /**
     * The cases of a level-1 golden file, by the engine's function name ("pace.curva").
     *
     * @return list<array{input: array<string, mixed>, expected: mixed}>
     */
    public static function cases(string $function): array
    {
        return Fixtures::json('golden/level1/' . $function . '.json')['cases'];
    }

    /**
     * @return array<string, mixed>
     */
    public static function manifest(): array
    {
        return Fixtures::json('golden/MANIFEST.json');
    }

    /**
     * "semana" | "fds" | "feriado" => NightType.
     */
    public static function nightType(string $engineName): NightType
    {
        return NightType::from(self::manifest()['vocabulary']['night_type'][$engineName]);
    }

    /**
     * "frente" | "ritmo" | "atras" | "muito_atras" => PaceStatus.
     */
    public static function paceStatus(string $engineName): PaceStatus
    {
        return PaceStatus::from(self::manifest()['vocabulary']['pace_status'][$engineName]);
    }

    /**
     * The engine's short property name => the property id in the parity preset.
     */
    public static function propertyId(string $engineName): string
    {
        return self::manifest()['vocabulary']['property'][$engineName];
    }

    /**
     * The engine's short property name => the tier of that property in the parity preset.
     */
    public static function tier(string $engineName): string
    {
        return self::manifest()['vocabulary']['tier'][$engineName];
    }
}
